//! OpenFX plug-ins and the project: their values as the host's (time in
//! frames, keyframes, defaults), and media generated by a plug-in — a
//! reader whose pictures a generator plug-in draws.

use std::collections::BTreeMap;
use std::sync::Arc;

use bv_core::{FrameRate, ImageRgbaF32, Tick};
use bv_ofx::{Animation, Context, Handles, Instance, Interp, Key, RenderRequest, Setup, Value};
use bv_timeline::{Generator, KeyCurve, KeyHandles, PluginFx, PluginKey, PluginParam, PluginValue};

use crate::{MediaError, Result, VideoReader};

/// `t` in frames of `rate` (OpenFX counts time in frames).
pub fn frames(t: Tick, rate: FrameRate) -> f64 {
    t.as_seconds_f64() * rate.as_f64()
}

/// `frames` of `rate` as a time.
pub fn time_of(frames: f64, rate: FrameRate) -> Tick {
    Tick::from_seconds_f64(frames / rate.as_f64())
}

pub fn interp(c: KeyCurve) -> Interp {
    match c {
        KeyCurve::Linear => Interp::Linear,
        KeyCurve::Fast => Interp::Fast,
        KeyCurve::Slow => Interp::Slow,
        KeyCurve::Smooth => Interp::Smooth,
        KeyCurve::Sharp => Interp::Sharp,
        KeyCurve::Hold => Interp::Hold,
        KeyCurve::Bezier => Interp::Bezier,
        KeyCurve::BezierSplit => Interp::BezierSplit,
    }
}

pub fn key_curve(i: Interp) -> KeyCurve {
    match i {
        Interp::Linear => KeyCurve::Linear,
        Interp::Fast => KeyCurve::Fast,
        Interp::Slow => KeyCurve::Slow,
        Interp::Smooth => KeyCurve::Smooth,
        Interp::Sharp => KeyCurve::Sharp,
        Interp::Hold => KeyCurve::Hold,
        Interp::Bezier => KeyCurve::Bezier,
        Interp::BezierSplit => KeyCurve::BezierSplit,
    }
}

/// A keyframe's handles as the host's (in frames)...
fn host_handles(h: &[KeyHandles], rate: FrameRate) -> Vec<Handles> {
    h.iter()
        .map(|h| Handles {
            before: [frames(h.before.0, rate), h.before.1],
            after: [frames(h.after.0, rate), h.after.1],
        })
        .collect()
}

/// ...and the host's as the project's.
fn key_handles(h: &[Handles], rate: FrameRate) -> Vec<KeyHandles> {
    h.iter()
        .map(|h| KeyHandles {
            before: (time_of(h.before[0], rate), h.before[1]),
            after: (time_of(h.after[0], rate), h.after[1]),
        })
        .collect()
}

/// The handles keyframe `i` of `p` has for each of its numbers as its
/// curve is drawn: its own, or those that follow the keyframes around it.
pub fn handles(p: &PluginParam, i: usize, rate: FrameRate) -> Vec<KeyHandles> {
    let Some(PluginValue::Num(v)) = p.keys.get(i).map(|k| &k.value) else {
        return Vec::new();
    };
    let a = animation(p, rate);
    let all: Vec<Handles> = (0..v.len()).map(|d| a.handles(i, d)).collect();
    key_handles(&all, rate)
}

/// Gives keyframe `i` of `p` the curve `curve`. Made a Bézier one, its
/// handles keep the curve as it was — on each side the slope it has
/// there (locked: their mean, both as long), a third of the way to the
/// keyframe beside it; turned from split to locked, the one before lines
/// up with the one after; another curve drops them.
pub fn set_curve(p: &mut PluginParam, i: usize, curve: KeyCurve, rate: FrameRate) {
    let Some(was) = p.keys.get(i).map(|k| k.curve) else {
        return;
    };
    if !curve.is_bezier() {
        p.keys[i].curve = curve;
        p.keys[i].handles.clear();
        return;
    }
    if was.is_bezier() {
        if p.keys[i].handles.is_empty() {
            p.keys[i].handles = handles(p, i, rate);
        }
    } else {
        p.keys[i].handles = fitted_handles(p, i, curve, rate);
    }
    p.keys[i].curve = curve;
    if curve == KeyCurve::Bezier {
        for h in &mut p.keys[i].handles {
            h.before = (Tick(-h.after.0.0), -h.after.1);
        }
    }
}

/// The handles that keep keyframe `i`'s curve as it is (see `set_curve`).
fn fitted_handles(p: &PluginParam, i: usize, curve: KeyCurve, rate: FrameRate) -> Vec<KeyHandles> {
    let k = &p.keys[i];
    let PluginValue::Num(v) = &k.value else {
        return Vec::new();
    };
    let num = |k: &PluginKey, d: usize| match &k.value {
        PluginValue::Num(v) => v.get(d).copied().unwrap_or(0.0),
        _ => 0.0,
    };
    let t = frames(k.at, rate);
    let prev = i.checked_sub(1).map(|j| &p.keys[j]);
    let next = p.keys.get(i + 1);
    // Each side's length (a third of the way to its neighbour; a lone
    // keyframe's ten frames).
    let len_before = prev.map(|b| (t - frames(b.at, rate)) / 3.0);
    let len_after = next.map(|n| (frames(n.at, rate) - t) / 3.0);
    let (len_before, len_after) = match (len_before, len_after) {
        (Some(b), Some(a)) => (b, a),
        (Some(b), None) => (b, b),
        (None, Some(a)) => (a, a),
        (None, None) => (10.0, 10.0),
    };
    let (len_before, len_after) = if curve == KeyCurve::Bezier {
        let l = len_before.min(len_after);
        (l, l)
    } else {
        (len_before, len_after)
    };
    (0..v.len())
        .map(|d| {
            // The slopes the curves on each side meet it with.
            let left = prev.map(|b| {
                let span = (t - frames(b.at, rate)).max(bv_ofx::value::SAME_TIME);
                interp(b.curve).slopes().1 * (num(k, d) - num(b, d)) / span
            });
            let right = next.map(|n| {
                let span = (frames(n.at, rate) - t).max(bv_ofx::value::SAME_TIME);
                interp(k.curve).slopes().0 * (num(n, d) - num(k, d)) / span
            });
            let (left, right) = match (left, right) {
                (Some(l), Some(r)) if curve == KeyCurve::Bezier => ((l + r) / 2.0, (l + r) / 2.0),
                (Some(l), Some(r)) => (l, r),
                (Some(l), None) => (l, l),
                (None, Some(r)) => (r, r),
                (None, None) => (0.0, 0.0),
            };
            KeyHandles {
                before: (time_of(-len_before, rate), -len_before * left),
                after: (time_of(len_after, rate), len_after * right),
            }
        })
        .collect()
}

/// Moves keyframe `i`'s handle for number `d` (the one after it, or the
/// one before) to `to` from the keyframe, kept on its side in time; a
/// locked keyframe's other handle goes equal and opposite.
pub fn set_handle(
    p: &mut PluginParam,
    i: usize,
    d: usize,
    after: bool,
    to: (Tick, f64),
    rate: FrameRate,
) {
    if !p.keys.get(i).is_some_and(|k| k.curve.is_bezier()) {
        return;
    }
    if p.keys[i].handles.is_empty() {
        p.keys[i].handles = handles(p, i, rate);
    }
    let locked = p.keys[i].curve == KeyCurve::Bezier;
    let Some(h) = p.keys[i].handles.get_mut(d) else {
        return;
    };
    let to = if after {
        (to.0.max(Tick::ZERO), to.1)
    } else {
        (to.0.min(Tick::ZERO), to.1)
    };
    let mirror = (Tick(-to.0.0), -to.1);
    if after {
        h.after = to;
        if locked {
            h.before = mirror;
        }
    } else {
        h.before = to;
        if locked {
            h.after = mirror;
        }
    }
}

/// A project's value as the host's.
pub fn value(v: &PluginValue) -> Value {
    match v {
        PluginValue::Num(n) => Value::Num(n.clone()),
        PluginValue::Text(t) => Value::Text(t.clone()),
        PluginValue::Bytes(b) => Value::Bytes(b.clone()),
        PluginValue::Curves(c) => Value::Curves(c.clone()),
    }
}

/// The host's value as the project's (`None` for groups, pages and
/// buttons).
pub fn plugin_value(v: &Value) -> Option<PluginValue> {
    Some(match v {
        Value::Num(n) => PluginValue::Num(n.clone()),
        Value::Text(t) => PluginValue::Text(t.clone()),
        Value::Bytes(b) => PluginValue::Bytes(b.clone()),
        Value::Curves(c) => PluginValue::Curves(c.clone()),
        Value::None => return None,
    })
}

/// A parameter of the project as the host's animation.
pub fn animation(p: &PluginParam, rate: FrameRate) -> Animation {
    Animation {
        value: value(&p.value),
        keys: p
            .keys
            .iter()
            .map(|k| Key {
                time: frames(k.at, rate),
                value: value(&k.value),
                interp: interp(k.curve),
                handles: host_handles(&k.handles, rate),
            })
            .collect(),
    }
}

/// The host's animation as a parameter of the project.
pub fn plugin_param(a: &Animation, rate: FrameRate) -> Option<PluginParam> {
    Some(PluginParam {
        value: plugin_value(&a.value)?,
        keys: a
            .keys
            .iter()
            .filter_map(|k| {
                Some(PluginKey {
                    at: time_of(k.time, rate),
                    value: plugin_value(&k.value)?,
                    curve: key_curve(k.interp),
                    handles: key_handles(&k.handles, rate),
                })
            })
            .collect(),
    })
}

/// Gives an instance the project's values: its parameters at their
/// defaults, then the ones the project sets.
pub fn sync_values(instance: &Instance, params: &BTreeMap<String, PluginParam>, rate: FrameRate) {
    let defaults: Vec<(String, Animation)> = instance
        .param_infos()
        .into_iter()
        .filter(|p| p.ty.has_value())
        .map(|p| (p.name, Animation::constant(p.default)))
        .collect();
    instance.set_values(&defaults);
    let values: Vec<(String, Animation)> = params
        .iter()
        .map(|(n, p)| (n.clone(), animation(p, rate)))
        .collect();
    instance.set_values(&values);
}

/// The context a filter-like effect runs in: filter when the plug-in has
/// it, general otherwise.
pub fn filter_context(info: &bv_ofx::PluginInfo) -> Option<Context> {
    FILTERS
        .into_iter()
        .find(|c| !info.files && info.contexts.contains(c))
}

/// The contexts a filter-like effect runs in, the first that works.
pub const FILTERS: [Context; 2] = [Context::Filter, Context::General];

/// Whether the plug-in draws transitions.
pub fn transition_context(info: &bv_ofx::PluginInfo) -> Option<Context> {
    (!info.files && info.contexts.contains(&Context::Transition)).then_some(Context::Transition)
}

/// The context a compositor runs in (a track's Custom compositing mode):
/// the General one, where it has a second input, the map.
pub fn compositor_context(info: &bv_ofx::PluginInfo) -> Option<Context> {
    (!info.files && info.contexts.contains(&Context::General)).then_some(Context::General)
}

/// Whether the plug-in draws pictures of its own (a generator; plug-ins
/// that read files are not: BananaV imports files itself).
pub fn generator_context(info: &bv_ofx::PluginInfo) -> Option<Context> {
    (!info.files && info.contexts.contains(&Context::Generator)).then_some(Context::Generator)
}

/// The size of a picture of `full` reduced as far as it still covers
/// `min` (never larger than `full`).
pub fn covering(full: (u32, u32), min: (u32, u32)) -> (u32, u32) {
    let k = (min.0 as f64 / full.0.max(1) as f64)
        .max(min.1 as f64 / full.1.max(1) as f64)
        .clamp(1e-3, 1.0);
    (
        ((full.0 as f64 * k).ceil() as u32).clamp(1, full.0.max(1)),
        ((full.1 as f64 * k).ceil() as u32).clamp(1, full.1.max(1)),
    )
}

/// Generator plug-in `fx`'s values at its media's instant `time` (a
/// frame of `rate`), as its instance has them: the media's values and
/// keyframes, the plug-in's defaults for the rest.
pub fn generator_values(
    fx: &PluginFx,
    rate: FrameRate,
    time: Tick,
) -> Option<Vec<(String, PluginValue)>> {
    let info = bv_ofx::registry().info(&fx.id)?;
    let described = info.context(generator_context(&info)?)?;
    let frame = rate.frame_at(time) as f64;
    Some(
        described
            .params
            .iter()
            .filter(|p| p.ty.has_value())
            .filter_map(|p| {
                let value = match fx.params.get(&p.name) {
                    Some(param) => animation(param, rate).at(frame, p.ty),
                    None => p.default.clone(),
                };
                Some((p.name.clone(), plugin_value(&value)?))
            })
            .collect(),
    )
}

/// Media a generator plug-in draws: its pictures in the values the
/// project composites on, as an 8-bit editor's generators draw them there
/// — video's encoded values in a project composited in video gamma (made
/// light here, as every reader's pictures are), light in one composited
/// in light.
pub(crate) struct PluginVideo {
    instance: Instance,
    rate: FrameRate,
    size: (u32, u32),
    /// The length the instance was told, in frames.
    span: f64,
    /// The project's: 8-bit pictures, composited on the encoded values.
    eight_bit: bool,
    encoded: bool,
    /// How its Media Properties read its pictures' alpha.
    alpha: bv_timeline::AlphaChannel,
    /// The last picture: its frame and size.
    cache: Option<(i64, (u32, u32), Arc<ImageRgbaF32>)>,
}

impl PluginVideo {
    /// Generator `fx`'s pictures, `width` × `height` pixels shaped
    /// `pixel_aspect` (width over height), at `rate`.
    pub(crate) fn new(
        fx: &PluginFx,
        width: u32,
        height: u32,
        pixel_aspect: f64,
        rate: FrameRate,
    ) -> Result<PluginVideo> {
        let failed = |e: bv_ofx::Error| MediaError::Unsupported(format!("{}: {e}", fx.name));
        let plugin = bv_ofx::registry().plugin(&fx.id).map_err(failed)?;
        let context = generator_context(&plugin.info).ok_or(MediaError::NoStream)?;
        let span = frames(Generator::DURATION, rate);
        let setup = Setup {
            frame_rate: rate.as_f64(),
            duration: span,
            size: (width as f64, height as f64),
            pixel_aspect: 1.0,
            interactive: false,
        };
        let instance = Instance::new(&plugin, context, &setup).map_err(failed)?;
        instance.set_media_pixel_aspect(pixel_aspect);
        sync_values(&instance, &fx.params, rate);
        Ok(PluginVideo {
            instance,
            rate,
            size: (width.max(1), height.max(1)),
            span,
            eight_bit: false,
            encoded: true,
            alpha: bv_timeline::AlphaChannel::Undefined,
            cache: None,
        })
    }
}

impl VideoReader for PluginVideo {
    fn frame_at(&mut self, t: Tick) -> Result<Arc<ImageRgbaF32>> {
        self.frame_at_scaled(t, u32::MAX, u32::MAX)
    }

    fn set_span(&mut self, span: Option<Tick>) {
        let span = frames(span.unwrap_or(Generator::DURATION), self.rate);
        if span != self.span {
            self.span = span;
            self.instance.set_duration(span);
            self.cache = None;
        }
    }

    fn set_alpha(&mut self, alpha: bv_timeline::AlphaChannel, _background: [u8; 3]) {
        if alpha != self.alpha {
            self.alpha = alpha;
            self.cache = None;
        }
    }

    fn set_project(&mut self, eight_bit: bool, encoded: bool) {
        if (eight_bit, encoded) != (self.eight_bit, self.encoded) {
            (self.eight_bit, self.encoded) = (eight_bit, encoded);
            self.instance.set_eight_bit(eight_bit);
            self.cache = None;
        }
    }

    fn frame_at_scaled(&mut self, t: Tick, min_w: u32, min_h: u32) -> Result<Arc<ImageRgbaF32>> {
        let frame = self.rate.frame_at(t);
        let (w, h) = covering(self.size, (min_w, min_h));
        if let Some((f, size, img)) = &self.cache
            && *f == frame
            && *size == (w, h)
        {
            return Ok(Arc::clone(img));
        }
        let req = RenderRequest {
            time: frame as f64,
            width: w,
            height: h,
            scale: w as f64 / self.size.0 as f64,
            draft: false,
            interactive: false,
            sequential: false,
            timeline: None,
        };
        let mut img = self
            .instance
            .render(&req)
            .map_err(|e| MediaError::Corrupt(e.to_string()))?;
        // A generator's pictures are premultiplied: read without alpha,
        // every pixel is opaque; read as straight, its colors are taken
        // as they are.
        match self.alpha {
            bv_timeline::AlphaChannel::None => {
                img.data.iter_mut().for_each(|px| px[3] = 1.0);
            }
            bv_timeline::AlphaChannel::Straight => {
                for px in &mut img.data {
                    let a = px[3];
                    px[0] *= a;
                    px[1] *= a;
                    px[2] *= a;
                }
            }
            _ => {}
        }
        if self.encoded {
            to_light(&mut img);
        }
        let img = Arc::new(img);
        self.cache = Some((frame, (w, h), Arc::clone(&img)));
        Ok(img)
    }
}

/// Premultiplied encoded values (video gamma, BT.709's) made light, on the
/// straight colors.
fn to_light(img: &mut ImageRgbaF32) {
    let w = img.width as usize;
    bv_color::convert::par_rows(&mut img.data, w, |_, row| {
        for px in row {
            let a = px[3];
            if a <= 0.0 {
                continue;
            }
            for c in &mut px[..3] {
                *c = bv_color::transfer::bt709_to_linear((*c / a).clamp(0.0, 1.0)) * a;
            }
        }
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reductions_cover_what_is_asked() {
        assert_eq!(covering((1920, 1080), (u32::MAX, u32::MAX)), (1920, 1080));
        assert_eq!(covering((1920, 1080), (480, 270)), (480, 270));
        // The larger of the two reductions: the picture covers both.
        assert_eq!(covering((1920, 1080), (960, 100)), (960, 540));
        assert_eq!(covering((1920, 1080), (0, 0)), (2, 2));
    }

    #[test]
    fn times_and_keys_in_frames() {
        let rate = FrameRate::FPS_30;
        assert_eq!(frames(Tick::from_seconds(2), rate), 60.0);
        assert_eq!(time_of(45.0, rate), Tick::from_seconds_f64(1.5));
        let p = PluginParam {
            value: PluginValue::Num(vec![1.0]),
            keys: vec![PluginKey {
                at: Tick::from_seconds(1),
                value: PluginValue::Num(vec![0.5]),
                curve: KeyCurve::Hold,
                handles: Vec::new(),
            }],
        };
        let a = animation(&p, rate);
        assert_eq!(a.keys[0].time, 30.0);
        assert_eq!(a.keys[0].interp, Interp::Hold);
        assert_eq!(plugin_param(&a, rate), Some(p));
    }

    /// A keyframe made a Bézier one keeps the curve; its handles move, a
    /// locked one's together, and go back and forth through the host.
    #[test]
    fn bezier_keyframes_keep_the_curve_and_move_their_handles() {
        let rate = FrameRate::FPS_30;
        let num = |v: f64| PluginValue::Num(vec![v]);
        let mut p = PluginParam {
            value: num(0.0),
            keys: vec![
                PluginKey::new(Tick::ZERO, num(0.0), KeyCurve::Smooth),
                PluginKey::new(Tick::from_seconds(1), num(1.0), KeyCurve::Linear),
                PluginKey::new(Tick::from_seconds(2), num(3.0), KeyCurve::Linear),
            ],
        };
        let at = |p: &PluginParam, s: f64| {
            animation(p, rate)
                .at(s * 30.0, bv_ofx::ParamType::Double)
                .num(0)
        };
        let before: Vec<f64> = (0..=40).map(|k| at(&p, k as f64 / 20.0)).collect();
        // Split: each side's slope, the curve as it was.
        set_curve(&mut p, 1, KeyCurve::BezierSplit, rate);
        assert_eq!(p.keys[1].handles.len(), 1);
        for (k, v) in before.iter().enumerate() {
            assert!((at(&p, k as f64 / 20.0) - v).abs() < 1e-6, "{k}");
        }
        assert_eq!(plugin_param(&animation(&p, rate), rate), Some(p.clone()));
        // Locked: the handle before lines up with the one after.
        set_curve(&mut p, 1, KeyCurve::Bezier, rate);
        let h = p.keys[1].handles[0];
        assert_eq!((h.before.0.0, h.before.1), (-h.after.0.0, -h.after.1));
        set_handle(&mut p, 1, 0, true, (Tick::from_seconds_f64(0.2), 0.5), rate);
        let h = p.keys[1].handles[0];
        assert_eq!(h.after, (Tick::from_seconds_f64(0.2), 0.5));
        assert_eq!(h.before, (Tick::from_seconds_f64(-0.2), -0.5));
        // Split, they part; a handle stays on its side in time.
        set_curve(&mut p, 1, KeyCurve::BezierSplit, rate);
        set_handle(&mut p, 1, 0, false, (Tick::from_seconds(1), 2.0), rate);
        let h = p.keys[1].handles[0];
        assert_eq!(h.before, (Tick::ZERO, 2.0));
        assert_eq!(h.after, (Tick::from_seconds_f64(0.2), 0.5));
        // Another curve drops them.
        set_curve(&mut p, 1, KeyCurve::Linear, rate);
        assert!(p.keys[1].handles.is_empty());
    }
}
